module benchmark/solution

import std/io (readLine)
import std/string (stringToInt)
import std/option (Some, None)

func readAndDouble() -> () ! {IO} {
  let line = readLine();
  if line == "" then ()
  else {
    match stringToInt(line) {
      Some(n) => println(show(n * 2)),
      None => ()
    };
    readAndDouble()
  }
}

export func main() -> () ! {IO} = readAndDouble()
